import React, { useState } from "react";
import { createDelivery } from "../api/deliveryApi";
import { useNavigate } from "react-router-dom";

export default function CreateDeliveryForm() {
  const navigate = useNavigate();

  const [form, setForm] = useState({
    customerId: "",
    lat: "",
    lng: "",
    status: "Assigned"
  });

  const [createdDelivery, setCreatedDelivery] = useState<any | null>(null);
  const [error, setError] = useState("");

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const res = await createDelivery({
        customerId: form.customerId,
        location: {
          lat: parseFloat(form.lat),
          lng: parseFloat(form.lng),
        },
        status: form.status
      });
      setCreatedDelivery(res.data); // show assigned driver
      setForm({ customerId: "", lat: "", lng: "", status: "Assigned" });
      setError("");
    } catch (err: any) {
      setError("❌ Failed to create delivery");
      setCreatedDelivery(null);
    }
  };

  return (
    <form
      onSubmit={handleSubmit}
      style={{
        padding: "30px",
        maxWidth: "400px",
        margin: "auto",
        backgroundColor: "#f9f9f9",
        borderRadius: "8px",
        border: "1px solid #ccc"
      }}
    >
      <h2 style={{ textAlign: "center" }}>Create Delivery</h2>

      {error && <p style={{ color: "red" }}>{error}</p>}

      <input
        type="text"
        name="customerId"
        placeholder="Customer ID"
        value={form.customerId}
        onChange={handleChange}
        required
        style={{ width: "100%", marginBottom: 12, padding: 10 }}
      />

      <input
        type="text"
        name="lat"
        placeholder="Latitude"
        value={form.lat}
        onChange={handleChange}
        required
        style={{ width: "100%", marginBottom: 12, padding: 10 }}
      />

      <input
        type="text"
        name="lng"
        placeholder="Longitude"
        value={form.lng}
        onChange={handleChange}
        required
        style={{ width: "100%", marginBottom: 12, padding: 10 }}
      />

      <select
        name="status"
        value={form.status}
        onChange={handleChange}
        style={{ width: "100%", marginBottom: 12, padding: 10 }}
      >
        <option value="Assigned">Assigned</option>
        <option value="Pending">Pending</option>
        <option value="In Transit">In Transit</option>
        <option value="Delivered">Delivered</option>
      </select>

      <button
        type="submit"
        style={{
          padding: "10px 20px",
          backgroundColor: "#007bff",
          color: "#fff",
          border: "none",
          width: "100%",
          borderRadius: 4
        }}
      >
        Create Delivery
      </button>

      <button
        type="button"
        onClick={() => navigate("/")}
        style={{
          marginTop: 15,
          padding: "10px 20px",
          backgroundColor: "#6c757d",
          color: "#fff",
          border: "none",
          width: "100%",
          borderRadius: 4
        }}
      >
        ← Back to Dashboard
      </button>

      {/* ✅ Inline Assigned Driver Info */}
      {createdDelivery && (
        <div
          style={{
            marginTop: 20,
            padding: 15,
            border: "1px solid #28a745",
            borderRadius: 4,
            backgroundColor: "#e6f9eb"
          }}
        >
          <p><strong>Delivery Created!</strong></p>
          <p>Customer: {createdDelivery.customerId}</p>
          <p>Driver Assigned: <strong>{createdDelivery.driverId}</strong></p>
        </div>
      )}
    </form>
  );
}
